action.mutation:
mutation UpdateReceipt($payload: [ReceiptUpdatePayloadInput!]!) {
  mutation: updateReceipt(payload: $payload) { 
    id
    number
  }
}

mutation UpdateReceiptLine($payload: [ReceiptLineUpdatePayloadInput!]!) {
  mutation: updateReceiptLine(payload: $payload) { 
    id
    number
  }
}
